package app.space.notes.runtime;

import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import androidx.recyclerview.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** Virtualized sparse grid: no enormous table or flattened editable import. */
final class SpreadsheetPreview extends LinearLayout implements AutoCloseable {
    private final NotesDesign design;private final SpreadsheetFile book;private final RecyclerView rows;private final HorizontalScrollView horizontal;private final LinearLayout gridColumn;private final GridRow headings;private final TextView status;private final EditText query;private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private SpreadsheetFile.Sheet sheet;private volatile boolean closed;private volatile int generation;private int matchIndex;private final ArrayList<int[]> matches=new ArrayList<>();private final int cellWidth,gutter,rowHeight;
    SpreadsheetPreview(Context context,NotesDesign design,SpreadsheetFile book,NotesHost host,Uri uri,String name){
        super(context);this.design=design;this.book=book;sheet=book.sheets.get(0);setOrientation(VERTICAL);cellWidth=design.dp(Math.max(140,(int)(90*getResources().getConfiguration().fontScale)));gutter=design.dp(64);rowHeight=design.dp(Math.max(48,16+(int)(24*getResources().getConfiguration().fontScale)));
        addView(design.label(name+" · viewed spreadsheet · not a saved Note/Doc",13,design.muted));
        TextView limits=design.label("Read-only raw cached values. Formatting, dates/currency, merged cells, charts and images are not reproduced; formulas/macros/links are never executed. Tap a cell for selectable value/formula. Original file is unchanged.",12,design.muted);limits.setMaxLines(2);limits.setEllipsize(android.text.TextUtils.TruncateAt.END);limits.setMinHeight(design.dp(48));limits.setOnClickListener(v->design.show(new android.app.AlertDialog.Builder(context).setTitle("Spreadsheet read options").setMessage("This is a sparse grid of stored cell values, not an Excel rendering engine. Number/date formatting, merges, charts and images are not reproduced. Formula values are cached and may be stale or missing. No formulas, macros, scripts or links run. Open original in a compatible reader for full fidelity; that reader has its own privacy policy. Your file is never modified. Viewer limits: 32 MiB input, 250,000 populated cells, 8 million characters, bounded decompression. The separate editable-note import remains limited to 100,000 characters.").setPositiveButton("OK",null).create()));addView(limits);
        LinearLayout tools=new LinearLayout(context);tools.addView(design.textAction("Sheet",this::chooseSheet),new LayoutParams(0,-2,1));tools.addView(design.textAction("Go to cell",this::goToCell),new LayoutParams(0,-2,1));tools.addView(design.textAction("Count",()->design.show(new android.app.AlertDialog.Builder(context).setTitle("Spreadsheet count").setMessage(book.sheets.size()+" sheets · "+book.cells+" populated cells\n"+book.characters+" UTF-16 units in cached values/formulas\nCurrent sheet: "+sheet.rowCount+" rows × "+sheet.columnCount+" columns, including sparse gaps.").setPositiveButton("OK",null).create())),new LayoutParams(0,-2,1));addView(tools);
        LinearLayout find=new LinearLayout(context);query=new EditText(context);query.setHint("Find values or formulas");query.setSingleLine(true);design.entry(query,15);find.addView(query,new LayoutParams(0,-2,1));find.addView(design.textAction("Find",this::find));find.addView(design.textAction("Next",this::next));addView(find);
        status=design.label("",13,design.muted);addView(status);LinearLayout copy=new LinearLayout(context);String mime=name.toLowerCase(Locale.ROOT).endsWith(".csv")?"text/csv":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";copy.addView(design.textAction("Save original copy",()->host.saveViewedCopy(uri,name,mime)),new LayoutParams(0,-2,1));copy.addView(design.textAction("Open original",()->host.openOriginal(uri,mime)),new LayoutParams(0,-2,1));addView(copy);
        horizontal=new HorizontalScrollView(context);horizontal.setFillViewport(false);rows=new RecyclerView(context);rows.setLayoutManager(new LinearLayoutManager(context));rows.setItemViewCacheSize(1);gridColumn=new LinearLayout(context);gridColumn.setOrientation(VERTICAL);headings=new GridRow();headings.row=0;gridColumn.addView(headings,new LinearLayout.LayoutParams(-1,rowHeight));gridColumn.addView(rows,new LinearLayout.LayoutParams(-1,0,1));horizontal.addView(gridColumn,new HorizontalScrollView.LayoutParams(width(),-1));addView(horizontal,new LayoutParams(-1,0,1));
        horizontal.setOnScrollChangeListener((View.OnScrollChangeListener)(view,x,y,oldX,oldY)->{headings.invalidate();for(int i=0;i<rows.getChildCount();i++)rows.getChildAt(i).invalidate();});setSheet(0);
    }
    private int width(){return gutter+Math.max(1,sheet.columnCount)*cellWidth;}
    private void setSheet(int index){generation++;matches.clear();sheet=book.sheets.get(index);gridColumn.setLayoutParams(new HorizontalScrollView.LayoutParams(width(),-1));headings.invalidate();rows.setAdapter(new GridAdapter());horizontal.scrollTo(0,0);status.setText(sheet.name+" · "+sheet.rowCount+" rows × "+sheet.columnCount+" columns");}
    private void chooseSheet(){String[] names=new String[book.sheets.size()];for(int i=0;i<names.length;i++)names[i]=book.sheets.get(i).name;design.show(new android.app.AlertDialog.Builder(getContext()).setTitle("Worksheets · saved workbook order").setItems(names,(dialog,index)->setSheet(index)).setNegativeButton("Cancel",null).create());}
    private void goToCell(){EditText field=new EditText(getContext());field.setHint("A1");design.show(new android.app.AlertDialog.Builder(getContext()).setTitle("Go to cell").setView(field).setPositiveButton("Go",(d,w)->{try{String reference=field.getText().toString().trim().toUpperCase(Locale.ROOT);String digits=reference.replaceFirst("^[A-Z]+","");int row=Integer.parseInt(digits),column=SpreadsheetFile.column(reference,row);if(row>sheet.rowCount || column>sheet.columnCount)throw new IllegalArgumentException();jump(row,column);cell(row,column);}catch(Exception invalid){status.setText("Enter a cell within the current sheet's used bounds");}}).setNegativeButton("Cancel",null).create());}
    private void jump(int row,int column){rows.scrollToPosition(row-1);horizontal.scrollTo(Math.max(0,(column-1)*cellWidth),0);status.setText(sheet.name+" · "+SpreadsheetFile.letters(column)+row);}
    private void find(){String needle=query.getText().toString().trim().toLowerCase(Locale.ROOT);int token=++generation;matches.clear();if(needle.isEmpty()){status.setText("Enter text to find");return;}if(needle.length()>512){status.setText("Search text is too long");return;}SpreadsheetFile.Sheet source=sheet;status.setText("Searching current sheet's values and formulas…");worker.execute(()->{try{ArrayList<int[]> found=new ArrayList<>();int count=0;for(Map.Entry<Integer,TreeMap<Integer,SpreadsheetFile.Cell>> row:source.rows.entrySet()){if(closed || token!=generation)return;for(Map.Entry<Integer,SpreadsheetFile.Cell> entry:row.getValue().entrySet()){SpreadsheetFile.Cell cell=entry.getValue();if(cell.value.toLowerCase(Locale.ROOT).contains(needle) || cell.formula.toLowerCase(Locale.ROOT).contains(needle)){count++;if(found.size()<10000)found.add(new int[]{row.getKey(),entry.getKey()});}}}int total=count;post(()->{if(closed || token!=generation)return;matches.addAll(found);matchIndex=-1;if(!matches.isEmpty())next();status.setText(total+" matching cells in "+source.name+(total>found.size()?" · first 10,000 navigable":""));});}catch(Exception | OutOfMemoryError failure){post(()->{if(!closed && token==generation)status.setText("Search could not finish; grid and original retained");});}});}
    private void next(){if(matches.isEmpty()){find();return;}matchIndex=(matchIndex+1)%matches.size();int[] cell=matches.get(matchIndex);jump(cell[0],cell[1]);status.setText("Matching cell "+(matchIndex+1)+" / "+matches.size()+" · "+SpreadsheetFile.letters(cell[1])+cell[0]);}
    private void cell(int row,int column){SpreadsheetFile.Cell cell=sheet.cell(row,column);String value=cell==null?"":cell.value;TextView text=design.label(value+(cell!=null && !cell.formula.isEmpty()?"\n\nStored formula (not evaluated):\n"+cell.formula:""),17,design.ink);text.setTextIsSelectable(true);text.setPadding(design.dp(16),design.dp(12),design.dp(16),design.dp(12));ScrollView scroll=new ScrollView(getContext());scroll.addView(text);design.show(new android.app.AlertDialog.Builder(getContext()).setTitle(sheet.name+" · "+SpreadsheetFile.letters(column)+row).setView(scroll).setPositiveButton("Copy cached value",(d,w)->{try{((ClipboardManager)getContext().getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Spreadsheet cached value",value));}catch(RuntimeException unavailable){status.setText("Clipboard unavailable; original unchanged");}}).setNegativeButton("Close",null).create());}
    private final class GridRow extends View {
        final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);int row;float downX,downY;
        GridRow(){super(SpreadsheetPreview.this.getContext());setFocusable(true);setClickable(true);paint.setTextSize(14*getResources().getDisplayMetrics().scaledDensity);}
        @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.drawColor(design.surface);int first=Math.max(1,(horizontal.getScrollX()-gutter)/cellWidth+1),last=Math.min(Math.max(1,sheet.columnCount),(horizontal.getScrollX()+getResources().getDisplayMetrics().widthPixels)/cellWidth+2);paint.setColor(design.ink);
            for(int column=first;column<=last;column++){int x=gutter+(column-1)*cellWidth;String text;if(row==0)text=SpreadsheetFile.letters(column);else{SpreadsheetFile.Cell cell=sheet.cell(row,column);text=cell==null?"":cell.value.replace('\n',' ');}canvas.save();canvas.clipRect(x+design.dp(6),0,x+cellWidth-design.dp(6),rowHeight);canvas.drawText(text,0,Math.min(text.length(),160),x+design.dp(8),rowHeight*.63f,paint);canvas.restore();paint.setColor(design.outline);canvas.drawLine(x,0,x,rowHeight,paint);paint.setColor(design.ink);}
            paint.setColor(design.background);canvas.drawRect(0,0,gutter,rowHeight,paint);paint.setColor(design.muted);canvas.drawText(row==0?"":Integer.toString(row),design.dp(6),rowHeight*.63f,paint);paint.setColor(design.outline);canvas.drawLine(0,rowHeight-1,width(),rowHeight-1,paint);
        }
        @Override public boolean onTouchEvent(MotionEvent event){if(event.getActionMasked()==MotionEvent.ACTION_DOWN){downX=event.getX();downY=event.getY();return true;}if(event.getActionMasked()==MotionEvent.ACTION_UP){if(Math.abs(event.getX()-downX)<design.dp(12) && Math.abs(event.getY()-downY)<design.dp(12) && row>0){int column=(int)((event.getX()-gutter)/cellWidth)+1;if(event.getX()>=gutter && column<=sheet.columnCount){performClick();cell(row,column);}}return true;}return true;}
        @Override public boolean performClick(){return super.performClick();}
    }
    private final class GridAdapter extends RecyclerView.Adapter<RecyclerView.ViewHolder>{
        @Override public int getItemCount(){return Math.max(1,sheet.rowCount);}
        @Override public RecyclerView.ViewHolder onCreateViewHolder(ViewGroup parent,int type){GridRow view=new GridRow();view.setLayoutParams(new RecyclerView.LayoutParams(width(),rowHeight));return new RecyclerView.ViewHolder(view){};}
        @Override public void onBindViewHolder(RecyclerView.ViewHolder holder,int row){GridRow view=(GridRow)holder.itemView;view.row=row+1;view.setContentDescription("Spreadsheet row "+(row+1)+"; tap a cell to read and copy, or use Go to cell");view.invalidate();}
    }
    @Override public void close(){if(closed)return;closed=true;generation++;worker.shutdownNow();rows.setAdapter(null);matches.clear();}
}
